import React, { useEffect, useState } from "react";
import { User } from "../../pages/Users";
import { deriveStatus } from "../../../shared/types";
import { StatusBadge } from "../../../shared/StatusBadge";
import { Avatar } from "../../../shared/Avatar";

interface Props {
  user: User;
  onClose: () => void;
  onSuspend?: (user: User) => void;
}

const USER_TYPE_LABEL: Record<string, string> = {
  "find work": "Freelancer",
  "hire talent": "Client",
};

type Tab = "basic" | "jobs" | "financial";

/* ─── colour tokens (matching existing app palette) ──────────── */
const ORANGE = "#EA580C";
const NAVY = "#0F172A";
const SLATE = "#64748B";
const BORDER = "#E2E8F0";
const BG = "#F8FAFC";

/* ─── small helpers ──────────────────────────────────────────── */
const Label: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <span
    style={{
      fontSize: 11,
      fontWeight: 600,
      color: SLATE,
      textTransform: "uppercase",
      letterSpacing: 0.8,
    }}
  >
    {children}
  </span>
);

const Value: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <span style={{ fontSize: 14, color: NAVY, fontWeight: 500 }}>{children}</span>
);

const EmptyValue: React.FC = () => (
  <span style={{ fontSize: 14, color: "#CBD5E1" }}>—</span>
);

const InfoField: React.FC<{ label: string; value?: React.ReactNode }> = ({
  label,
  value,
}) => (
  <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
    <Label>{label}</Label>
    {value ? <Value>{value}</Value> : <EmptyValue />}
  </div>
);

const SectionCard: React.FC<{
  title: string;
  children: React.ReactNode;
}> = ({ title, children }) => (
  <div
    style={{
      background: "#fff",
      border: `1px solid ${BORDER}`,
      borderRadius: 12,
      overflow: "hidden",
    }}
  >
    <div
      style={{
        padding: "12px 20px",
        borderBottom: `1px solid ${BORDER}`,
        background: BG,
      }}
    >
      <span
        style={{
          fontSize: 12,
          fontWeight: 700,
          color: NAVY,
          textTransform: "uppercase",
          letterSpacing: 0.8,
        }}
      >
        {title}
      </span>
    </div>
    <div style={{ padding: "16px 20px" }}>{children}</div>
  </div>
);

const Chip: React.FC<{ label: string; accent?: boolean }> = ({
  label,
  accent,
}) => (
  <span
    style={{
      padding: "4px 12px",
      borderRadius: 20,
      fontSize: 12,
      fontWeight: 500,
      background: accent ? "#FFF7ED" : BG,
      color: accent ? ORANGE : "#475569",
      border: `1px solid ${accent ? "#FDBA74" : BORDER}`,
      display: "inline-block",
    }}
  >
    {label}
  </span>
);

/* ─── TAB: Basic Info ─────────────────────────────────────────── */
const BasicInfoTab: React.FC<{ user: User }> = ({ user }) => {
  const types = (user.user_type_names ?? [])
    .map((t) => USER_TYPE_LABEL[t.toLowerCase()] ?? t)
    .join(", ");

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
      {/* Contact & Identity */}
      <SectionCard title="Basic Info">
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "1fr 1fr",
            gap: "14px 24px",
          }}
        >
          <InfoField label="Mobile No." value={user.phone} />
          <InfoField
            label="Email"
            value={
              /* email not on User type but show placeholder gracefully */
              (user as any).email
            }
          />
          <InfoField
            label="Location"
            value={(user.location_names ?? []).join(", ") || user.location}
          />
          <InfoField label="User Type" value={types} />
          <InfoField
            label="Joined"
            value={
              user.created_at
                ? new Date(user.created_at).toLocaleDateString("en-GB", {
                    year: "numeric",
                    month: "long",
                    day: "numeric",
                  })
                : undefined
            }
          />
          <InfoField
            label="Location Allowed"
            value={
              user.location_allowed === true
                ? "Yes"
                : user.location_allowed === false
                ? "No"
                : undefined
            }
          />
        </div>
      </SectionCard>

      {/* About */}
      {user.about_me && (
        <SectionCard title="About">
          <p
            style={{
              margin: 0,
              fontSize: 14,
              color: "#334155",
              lineHeight: 1.7,
            }}
          >
            {user.about_me}
          </p>
        </SectionCard>
      )}

      {/* Skills */}
      <SectionCard title="Skills">
        {user.skills_id?.length > 0 ? (
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
            {user.skills_id.map((s, i) => (
              <Chip key={i} label={s} />
            ))}
          </div>
        ) : (
          <EmptyValue />
        )}
      </SectionCard>

      {/* Preferred project types — if present on user object */}
      {(user as any).preferred_project_types?.length > 0 && (
        <SectionCard title="Preferred Project Types">
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
            {(user as any).preferred_project_types.map(
              (t: string, i: number) => (
                <Chip key={i} label={t} accent />
              )
            )}
          </div>
        </SectionCard>
      )}

      {/* Certifications */}
      <SectionCard title="Certifications">
        {user.certifications?.length > 0 ? (
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {user.certifications.map((c, i) => (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 10,
                  padding: "8px 12px",
                  background: BG,
                  borderRadius: 8,
                  border: `1px solid ${BORDER}`,
                }}
              >
                <span
                  style={{
                    width: 6,
                    height: 6,
                    borderRadius: "50%",
                    background: ORANGE,
                    flexShrink: 0,
                  }}
                />
                <span style={{ fontSize: 14, color: NAVY }}>{c}</span>
              </div>
            ))}
          </div>
        ) : (
          <EmptyValue />
        )}
      </SectionCard>

      {/* Availability & Rate */}
      {((user as any).hourly_rate ||
        (user as any).availability ||
        (user as any).timezone) && (
        <SectionCard title="Availability">
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr 1fr",
              gap: "14px 24px",
            }}
          >
            {(user as any).hourly_rate && (
              <InfoField
                label="Hourly Rate"
                value={`$${(user as any).hourly_rate}/Hour`}
              />
            )}
            {(user as any).availability && (
              <InfoField label="Availability" value={(user as any).availability} />
            )}
            {(user as any).timezone && (
              <InfoField label="Time Zone" value={(user as any).timezone} />
            )}
          </div>
        </SectionCard>
      )}

      {/* Portfolio */}
      {(user as any).portfolio_items?.length > 0 && (
        <SectionCard title={`Portfolio Items (${(user as any).portfolio_items.length})`}>
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr",
              gap: 12,
            }}
          >
            {(user as any).portfolio_items.map(
              (item: { title: string; link: string }, i: number) => (
                <div
                  key={i}
                  style={{
                    padding: "12px 14px",
                    border: `1px solid ${BORDER}`,
                    borderRadius: 10,
                    background: BG,
                  }}
                >
                  <div
                    style={{
                      fontSize: 11,
                      color: SLATE,
                      marginBottom: 4,
                      textTransform: "uppercase",
                      letterSpacing: 0.6,
                    }}
                  >
                    Project Title
                  </div>
                  <div
                    style={{
                      fontSize: 13,
                      fontWeight: 600,
                      color: NAVY,
                      marginBottom: 6,
                    }}
                  >
                    {item.title}
                  </div>
                  {item.link && (
                    <>
                      <div
                        style={{
                          fontSize: 11,
                          color: SLATE,
                          marginBottom: 2,
                          textTransform: "uppercase",
                          letterSpacing: 0.6,
                        }}
                      >
                        Link
                      </div>
                      <a
                        href={item.link}
                        target="_blank"
                        rel="noopener noreferrer"
                        style={{ fontSize: 13, color: ORANGE }}
                      >
                        {item.link}
                      </a>
                    </>
                  )}
                </div>
              )
            )}
          </div>
        </SectionCard>
      )}

      {/* Attachments */}
      {user.profile_attachments?.length > 0 && (
        <SectionCard title="Attachments">
          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            {user.profile_attachments.map((att, i) => (
              <a
                key={i}
                href={att}
                target="_blank"
                rel="noopener noreferrer"
                style={{
                  fontSize: 13,
                  color: ORANGE,
                  display: "flex",
                  alignItems: "center",
                  gap: 6,
                }}
              >
                <svg
                  width="14"
                  height="14"
                  viewBox="0 0 16 16"
                  fill="none"
                  style={{ flexShrink: 0 }}
                >
                  <path
                    d="M14 10v2a2 2 0 01-2 2H4a2 2 0 01-2-2v-2M8 2v8M5 5l3-3 3 3"
                    stroke={ORANGE}
                    strokeWidth="1.5"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
                {att}
              </a>
            ))}
          </div>
        </SectionCard>
      )}
    </div>
  );
};

/* ─── TAB: Current Jobs ───────────────────────────────────────── */
const CurrentJobsTab: React.FC<{ user: User }> = ({ user }) => {
  const jobs: any[] = (user as any).current_jobs ?? [];
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
      {jobs.length === 0 ? (
        <div
          style={{
            padding: "48px 0",
            textAlign: "center",
            color: "#94A3B8",
            fontSize: 14,
          }}
        >
          No current jobs on record
        </div>
      ) : (
        jobs.map((job: any, i: number) => (
          <SectionCard key={i} title={job.title ?? `Job ${i + 1}`}>
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 1fr",
                gap: "12px 24px",
              }}
            >
              {job.client && <InfoField label="Client" value={job.client} />}
              {job.status && <InfoField label="Status" value={job.status} />}
              {job.budget && <InfoField label="Budget" value={job.budget} />}
              {job.started_at && (
                <InfoField
                  label="Started"
                  value={new Date(job.started_at).toLocaleDateString("en-GB")}
                />
              )}
              {job.description && (
                <div style={{ gridColumn: "1 / -1" }}>
                  <InfoField label="Description" value={job.description} />
                </div>
              )}
            </div>
          </SectionCard>
        ))
      )}
    </div>
  );
};

/* ─── TAB: Financial Status ───────────────────────────────────── */
const FinancialTab: React.FC<{ user: User }> = ({ user }) => {
  const fin = (user as any).financial ?? {};
  const totalWorkedHours = (user as any).total_worked_hours;
  const totalWorkedProjects = (user as any).total_worked_projects;
  const totalEarned = (user as any).total_earned;

  const hasData =
    totalEarned ||
    totalWorkedHours ||
    totalWorkedProjects ||
    Object.keys(fin).length > 0;

  if (!hasData) {
    return (
      <div
        style={{
          padding: "48px 0",
          textAlign: "center",
          color: "#94A3B8",
          fontSize: 14,
        }}
      >
        No financial data available
      </div>
    );
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
      <SectionCard title="Overview">
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(3, 1fr)",
            gap: 12,
          }}
        >
          {[
            {
              label: "Total Worked",
              value:
                totalWorkedHours && totalWorkedProjects
                  ? `${totalWorkedHours} Hrs / ${totalWorkedProjects} Projects`
                  : totalWorkedHours
                  ? `${totalWorkedHours} Hrs`
                  : totalWorkedProjects
                  ? `${totalWorkedProjects} Projects`
                  : null,
            },
            {
              label: "Total Earned",
              value: totalEarned ? `$${totalEarned}` : null,
            },
            {
              label: "Balance",
              value: fin.balance ? `$${fin.balance}` : null,
            },
          ]
            .filter((s) => s.value)
            .map((stat, i) => (
              <div
                key={i}
                style={{
                  background: BG,
                  border: `1px solid ${BORDER}`,
                  borderRadius: 10,
                  padding: "14px 16px",
                }}
              >
                <div
                  style={{
                    fontSize: 11,
                    fontWeight: 600,
                    color: SLATE,
                    textTransform: "uppercase",
                    letterSpacing: 0.8,
                    marginBottom: 6,
                  }}
                >
                  {stat.label}
                </div>
                <div style={{ fontSize: 18, fontWeight: 700, color: NAVY }}>
                  {stat.value}
                </div>
              </div>
            ))}
        </div>
      </SectionCard>

      {Object.keys(fin).length > 0 && (
        <SectionCard title="Details">
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr",
              gap: "12px 24px",
            }}
          >
            {Object.entries(fin).map(([k, v]) => (
              <InfoField
                key={k}
                label={k.replace(/_/g, " ")}
                value={String(v)}
              />
            ))}
          </div>
        </SectionCard>
      )}
    </div>
  );
};

